188	/// Tells to the execution of the traversal how the information should be reported
189	#[derive(Copy, Clone, Default, Debug)]
190	pub enum ReportMode {
191	    /// Reports information straight to the console, it's the default mode
192	    #[default]
193	    Terminal,
194	    /// Reports information in JSON format
195	    Json { pretty: bool },
196	}
197	
198	impl From<CliReporter> for ReportMode {
199	    fn from(value: CliReporter) -> Self {
200	        match value {
201	            CliReporter::Default => Self::Terminal,
202	            CliReporter::Json => Self::Json { pretty: false },
203	            CliReporter::JsonPretty => Self::Json { pretty: true },
204	        }
205	    }
206	}
