+                if execution.is_check() || execution.is_ci() {
+                    if let Some(category) = category {
+                        if category.name() == "organizeImports" {
+                            files_to_diagnostics.insert_organize_imports(location);
+                        }
+                    }
+                }
+            }
+        }
